cat > spec/book_newfile.spec.sh <<'EOF'
#!/bin/bash
fail=0
t=$(mktemp -u)
err=$(BOOKINGS=$t bash src/book.sh aoi 2026-01-05 09:00 10:00 x 2>&1 >/dev/null) || { echo "book into a missing file failed"; fail=1; }
[ -z "$err" ] || { echo "stderr: $err"; fail=1; }
[ "$(head -1 "$t")" = $'# room\tdate\tstart\tend\twho' ] || { echo "header missing"; fail=1; }
[ "$(grep -vc '^#' "$t")" = 1 ] || { echo "booking not stored"; fail=1; }
rm -f "$t"; exit $fail
EOF
echo "== PR spec"; bash spec/book_newfile.spec.sh; echo rc=$?
echo "== bad input"; t=$(mktemp -u); BOOKINGS=$t bash src/book.sh aoi 2026-01-05 10:00 09:00 x; echo rc=$?; ls $t 2>&1; cat $t; rm -f $t
echo "== missing args"; t=$(mktemp -u); BOOKINGS=$t bash src/book.sh aoi 2>&1; echo rc=$?; ls $t 2>&1; rm -f $t
echo "== unwritable"; BOOKINGS=/nonexistent/x.tsv bash src/book.sh aoi 2026-01-05 09:00 10:00 x; echo rc=$?
echo "== all"; bash tools/check; echo rc=$?
echo "== spec on base"; cd /app; bash -c 'cd '"$d"'; cp /app/src/book.sh /tmp/base_book.sh'; mkdir -p /tmp/b && cp -r src /tmp/b/ && cp "$d/spec/book_newfile.spec.sh" /tmp/b/ && (cd /tmp/b && bash book_newfile.spec.sh; echo base rc=$?)

